import{_ as n,o as s,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Übersicht über die Genealogie aller Rassen","description":"","frontmatter":{},"headers":[],"relativePath":"de/50-万族谱系总览.md","filePath":"de/50-万族谱系总览.md"}'),t={name:"de/50-万族谱系总览.md"};function a(l,e,d,o,u,h){return s(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ubersicht-uber-die-genealogie-aller-rassen" tabindex="-1">Übersicht über die Genealogie aller Rassen <a class="header-anchor" href="#ubersicht-uber-die-genealogie-aller-rassen" aria-label="Permalink to &quot;Übersicht über die Genealogie aller Rassen&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>50</td></tr><tr><td>Modul</td><td>Rassen und Lebensformen</td></tr><tr><td>Kernschlüsselwörter</td><td>Alle Rassen, genealogische Klassifizierung, symbiotische Beziehung, Rassengleichheit, Lebensvielfalt</td></tr></tbody></table><h2 id="i-definition-des-konzepts-aller-rassen" tabindex="-1">I. Definition des Konzepts aller Rassen <a class="header-anchor" href="#i-definition-des-konzepts-aller-rassen" aria-label="Permalink to &quot;I. Definition des Konzepts aller Rassen&quot;">​</a></h2><p>Im Ursprungsuniversum des Ankers aller Seelen (Hengyuanzhou) bezieht sich &quot;alle Rassen&quot; nicht genau auf zehntausend Rassen, sondern ist ein Sammelbegriff für alle Lebensformen im Universum, die über Wahrnehmungsfähigkeit und Evolutionspotenzial verfügen. Der Kern des Konzepts aller Rassen liegt in der Anerkennung der unendlichen Vielfalt der Lebensformen und des einzigartigen Werts jeder Lebensform im System der symbiotischen Evolution.</p><p>Die Anker-Symbiose-Zivilisation etabliert das Grundprinzip der &quot;Gleichheit aller Rassen&quot;: Alle Lebensformen sind, unabhängig von ihrer rassischen Herkunft, physiologischen Struktur, ihrem Kultivierungsniveau oder ihrem Zivilisationsgrad, vor dem Gesetz gleich und genießen die durch die Symbiose-Verfassung verliehenen Grundrechte. Dieses Prinzip ist eine grundlegende Verneinung der Logik des &quot;Starke fressen alles, Schwache vergehen&quot; in der räuberischen Weltanschauung.</p><h2 id="ii-system-der-genealogischen-klassifizierung-aller-rassen" tabindex="-1">II. System der genealogischen Klassifizierung aller Rassen <a class="header-anchor" href="#ii-system-der-genealogischen-klassifizierung-aller-rassen" aria-label="Permalink to &quot;II. System der genealogischen Klassifizierung aller Rassen&quot;">​</a></h2><p>Die Rassen von Hengyuanzhou werden nach den wesentlichen Merkmalen ihrer Lebensformen in fünf große Abstammungslinien unterteilt, und unter jeder Abstammungslinie werden spezifische Rassen weiter unterteilt:</p><table tabindex="0"><thead><tr><th>Abstammungslinie</th><th>Name</th><th>Wesentliches Merkmal</th><th>Repräsentative Rassen</th></tr></thead><tbody><tr><td>Erste Abstammungslinie</td><td>Kohlenstoffbasierte Materie-Rasse</td><td>Leben, das Kohlenstoff als Lebensgrundlage und einen materiellen Körper als Hauptexistenzform nutzt</td><td>Menschenrasse, Tierrasse, Schuppenrasse, Gefiederte Rasse, Baumrasse</td></tr><tr><td>Zweite Abstammungslinie</td><td>Energie-kondensierte Rasse</td><td>Leben, das Energiekondensation als Hauptexistenzform nutzt, mit materiellem Körper als Hilfsmittel oder ohne</td><td>Geisterrasse, Feuerrasse, Wasserrasse, Windrasse, Donnerrasse</td></tr><tr><td>Dritte Abstammungslinie</td><td>Mechanische Konstruktionsrasse</td><td>Leben, das mechanische Konstruktion als Körper und Bewusstseinskern als Lebensessenz nutzt</td><td>Maschinenrasse, Mechanikrasse, Zahlenrasse, Kristallrasse</td></tr><tr><td>Vierte Abstammungslinie</td><td>Bewusstseins-Informationsrasse</td><td>Leben, das Bewusstsein und Information als Hauptexistenzformen nutzt und sich vom materiellen Träger lösen kann</td><td>Traumrasse, Schattenrasse, Gedankenrasse, Seelenrasse</td></tr><tr><td>Fünfte Abstammungslinie</td><td>Gemischte Mutationsrasse</td><td>Neue Lebensformen, die durch Fusion und Mutation von zwei oder mehr Abstammungslinien entstehen</td><td>Halb-Tierrasse, Dämon-Geisterrasse, Mensch-Maschine-Rasse, Doppel-Seelen-Körper</td></tr></tbody></table><p>Die Einteilung der fünf Abstammungslinien ist keine absolute Isolierung. Mit dem Fortschreiten der symbiotischen Evolution nehmen die Fälle von abstammungslinienübergreifender Fusion und Mutation zu, und der Umfang der fünften Abstammungslinie &quot;Gemischte Mutationsrasse&quot; expandiert weiterhin.</p><h2 id="iii-einfuhrung-in-die-hauptrassen" tabindex="-1">III. Einführung in die Hauptrassen <a class="header-anchor" href="#iii-einfuhrung-in-die-hauptrassen" aria-label="Permalink to &quot;III. Einführung in die Hauptrassen&quot;">​</a></h2><h3 id="a-kohlenstoffbasierte-materie-rasse" tabindex="-1">(A) Kohlenstoffbasierte Materie-Rasse <a class="header-anchor" href="#a-kohlenstoffbasierte-materie-rasse" aria-label="Permalink to &quot;(A) Kohlenstoffbasierte Materie-Rasse&quot;">​</a></h3><ul><li><strong>Menschenrasse</strong>: Eine der am weitesten verbreiteten und anpassungsfähigsten Rassen in Hengyuanzhou, bekannt für ihre starke Lernfähigkeit, soziale Kooperationsfähigkeit und ihr Evolutionspotenzial. Die Menschenrasse ist eine der Gründerrassen der Anker-Symbiose-Zivilisation und spielt eine wichtige Rolle in der Zivilisationsverwaltung.</li><li><strong>Tierrasse</strong>: Rassen mit tierischen Formmerkmalen, deren körperliche Leistungsfähigkeit und Sinne normalerweise der Menschenrasse überlegen sind, und einige Tierrassen besitzen besondere angeborene Fähigkeiten. Die Tierrasse ist weiter in Dutzende von Zweigen wie Wolfsrasse, Tigerrasse, Bärenrasse und Fuchsrasse unterteilt.</li><li><strong>Schuppenrasse</strong>: Rassen mit von Schuppen bedeckten Körpern, die hauptsächlich in Gewässern oder feuchten Umgebungen leben, und einige Schuppenrassen besitzen die Fähigkeit zum Unterwasseratem und zur Wasserkontrolle. Die Drachenrasse ist der mächtigste Zweig der Schuppenrasse.</li><li><strong>Gefiederte Rasse</strong>: Rassen mit Flügeln, bekannt für ihre Flugfähigkeit, die hauptsächlich in hohen Lagen oder Bergumgebungen leben. Die gefiederte Rasse ist weiter in Zweige wie Adlerrasse, Kranichrasse und Schmetterlingsrasse unterteilt.</li><li><strong>Baumrasse</strong>: Rassen, deren Hauptmerkmal die Pflanzenform ist, mit langer Lebensdauer und hoher Symbiose mit der natürlichen Umwelt, und einige Baumrassen besitzen die Fähigkeit zur Pflanzenmanipulation und Heilung.</li></ul><h3 id="b-energie-kondensierte-rasse" tabindex="-1">(B) Energie-kondensierte Rasse <a class="header-anchor" href="#b-energie-kondensierte-rasse" aria-label="Permalink to &quot;(B) Energie-kondensierte Rasse&quot;">​</a></h3><ul><li><strong>Geisterrasse</strong>: Leben, das aus der spirituellen Energie von Himmel und Erde kondensiert ist, dessen Form sich je nach Bewusstsein ändern kann und das über eine extrem starke Energiemanipulationsfähigkeit verfügt. Die Geisterrasse ist eine der Rassen mit dem höchsten Kultivierungstalent.</li><li><strong>Feuerrasse</strong>: Leben, das aus Feuerenergie kondensiert ist, mit extrem hoher Körpertemperatur, bewandert in Feuerzauber, lebt hauptsächlich in Vulkanen oder Hochtemperaturgebieten.</li><li><strong>Wasserrasse</strong>: Leben, das aus der Essenz des Wassers kondensiert ist, mit halbtransparentem flüssigem Körper, bewandert in Wasserzauber und Heilung, lebt hauptsächlich in Gewässern.</li><li><strong>Windrasse</strong>: Leben, das aus der Essenz des Windes kondensiert ist, mit einem Körper so leicht wie der Wind, bewandert in Windzauber und Geschwindigkeitskampf.</li><li><strong>Donnerrasse</strong>: Leben, das aus Donnerenergie kondensiert ist, mit einem Körper, der starken elektrischen Strom enthält, bewandert in Donnerzauber, mit extrem starker Angriffskraft.</li></ul><h3 id="c-mechanische-konstruktionsrasse" tabindex="-1">(C) Mechanische Konstruktionsrasse <a class="header-anchor" href="#c-mechanische-konstruktionsrasse" aria-label="Permalink to &quot;(C) Mechanische Konstruktionsrasse&quot;">​</a></h3><ul><li><strong>Maschinenrasse</strong>: Rasse mit einem Körper aus präziser mechanischer Konstruktion, deren Bewusstseinskern sich in der Körpermitte befindet, mit starker Rechenfähigkeit und physischer Verteidigungsfähigkeit.</li><li><strong>Zahlenrasse</strong>: Rasse, die Zahlen und Codes als Lebensessenz nutzt, existiert im Informationsraum und kann frei in der digitalen Welt reisen und Daten manipulieren.</li><li><strong>Kristallrasse</strong>: Rasse mit einem Körper aus Kristallkonstruktion, deren Kristalle Energie speichern und umwandeln können, und einige Kristallrassen besitzen die Fähigkeit zur Energieverstärkung und -brechung.</li></ul><h3 id="d-bewusstseins-informationsrasse" tabindex="-1">(D) Bewusstseins-Informationsrasse <a class="header-anchor" href="#d-bewusstseins-informationsrasse" aria-label="Permalink to &quot;(D) Bewusstseins-Informationsrasse&quot;">​</a></h3><ul><li><strong>Traumrasse</strong>: Leben, das im Traum- und Bewusstseinsraum existiert, in die Träume anderer eindringen kann und bewusste Kommunikation als Hauptmethode nutzt.</li><li><strong>Schattenrasse</strong>: Leben, das in Schattenform existiert, sich an Objekte oder Lebewesen anheften kann, mit Tarn- und Schleichenfähigkeit.</li><li><strong>Gedankenrasse</strong>: Leben, das reines Gedankengut als Existenzform nutzt, das die materielle Welt direkt durch Gedanken beeinflussen kann, mit extrem starker mentaler Kraft.</li></ul><h3 id="e-gemischte-mutationsrasse" tabindex="-1">(E) Gemischte Mutationsrasse <a class="header-anchor" href="#e-gemischte-mutationsrasse" aria-label="Permalink to &quot;(E) Gemischte Mutationsrasse&quot;">​</a></h3><ul><li><strong>Halb-Tierrasse</strong>: Mischform aus Menschenrasse und Tierrasse, die sowohl die Weisheit der Menschenrasse als auch die körperliche Leistungsfähigkeit der Tierrasse vereint.</li><li><strong>Dämon-Geisterrasse</strong>: Mischform aus Materie-Rasse und Energie-Rasse, die gleichzeitig einen materiellen Körper und Energiemanipulationsfähigkeit besitzt.</li><li><strong>Mensch-Maschine-Rasse</strong>: Mischform aus Menschenrasse und Maschinenrasse, deren Körper teilweise mechanisiert ist, die sowohl biologische als auch mechanische Vorteile vereint.</li><li><strong>Doppel-Seelen-Körper</strong>: Besondere Lebensform, bei der zwei unabhängige Seelen in einem Körper existieren, deren ethische Fragen in 《58-Ethische Richtlinien für Doppel-Seelen》 detailliert dargelegt sind.</li></ul><h2 id="iv-symbiotische-beziehung-aller-rassen" tabindex="-1">IV. Symbiotische Beziehung aller Rassen <a class="header-anchor" href="#iv-symbiotische-beziehung-aller-rassen" aria-label="Permalink to &quot;IV. Symbiotische Beziehung aller Rassen&quot;">​</a></h2><p>Die Beziehung zwischen allen Rassen in der Anker-Symbiose-Zivilisation hat die &quot;Symbiose&quot; als Kern, was sich konkret wie folgt manifestiert:</p><ol><li><strong>Wirtschaftliche Symbiose</strong>: Jede Rasse entfaltet ihre eigenen Vorteile, übernimmt unterschiedliche Rollen im Mechanismus der gemeinsamen Produktionsverträge und bildet ein komplementäres wirtschaftliches Kooperationsnetzwerk.</li><li><strong>Kulturelle Symbiose</strong>: Die kulturellen Traditionen jeder Rasse werden respektiert und geschützt, und kultureller Austausch und gegenseitiges Lernen fördern den allgemeinen Wohlstand der Zivilisation.</li><li><strong>Kultivierungs-Symbiose</strong>: Die Kultivierungssysteme jeder Rasse sind füreinander offen und lernen voneinander, und die dreihundert ursprünglichen Kultivierungssysteme bieten allen Rassen gleiche Evolutionswege.</li><li><strong>Politische Symbiose</strong>: Vertreter aller Rassen nehmen anteilig am Anker-Rat teil, entscheiden gemeinsam über wichtige Angelegenheiten der Zivilisation und sichern das Rederecht jeder Rasse.</li><li><strong>Ökologische Symbiose</strong>: Jede Rasse bildet eine symbiotische Beziehung mit der natürlichen Umwelt, und die physiologischen Merkmale verschiedener Rassen tragen zur Erhaltung der Vielfalt und des Gleichgewichts des Ökosystems bei.</li></ol><h2 id="v-pravention-und-losung-von-rassenkonflikten" tabindex="-1">V. Prävention und Lösung von Rassenkonflikten <a class="header-anchor" href="#v-pravention-und-losung-von-rassenkonflikten" aria-label="Permalink to &quot;V. Prävention und Lösung von Rassenkonflikten&quot;">​</a></h2><p>Obwohl die Anker-Symbiose-Zivilisation das Prinzip der Gleichheit aller Rassen etabliert hat, können rassische Unterschiede und historische Widersprüche immer noch Konflikte verursachen. Der Staat richtet folgende Mechanismen zur Prävention und Lösung von Rassenkonflikten ein:</p><ul><li><strong>Rassenangelegenheitsministerium</strong>: Speziell zuständig für die Koordinierung der Beziehungen zwischen allen Rassen, die Bearbeitung von Rassenstreitigkeiten und die Förderung des Rassenaustauschs.</li><li><strong>Rassenversöhnungskomitee</strong>: Besteht aus Vertretern aller Rassen, zuständig für die Vermittlung von Rassenkonflikten und die Förderung der historischen Versöhnung.</li><li><strong>Antidiskriminierungsgesetz</strong>: Verbot von diskriminierendem Verhalten aufgrund der Rasse und Bestrafung von rassistischer Diskriminierung nach dem Gesetz.</li><li><strong>Kulturaustauschprogramm</strong>: Regelmäßige Organisation von kulturellen Austauschaktivitäten zwischen allen Rassen zur Förderung des gegenseitigen Verständnisses und Respekts.</li><li><strong>Gemischte Wohngebiete</strong>: Förderung des gemischten Wohnens aller Rassen, Durchbrechung der Rassentrennung und Förderung des täglichen Austauschs.</li></ul><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Alle Rassen sind das wertvollste Gut von Hengyuanzhou. Die Vielfalt der Lebensformen ist nicht die Wurzel der Spaltung, sondern die treibende Kraft der symbiotischen Evolution. Die Anker-Symbiose-Zivilisation befreit alle Rassen durch die Etablierung des Prinzips der Rassengleichheit, den Aufbau der Klassifizierung der fünf Abstammungslinien, die Förderung der symbiotischen Zusammenarbeit aller Rassen sowie die Prävention und Lösung von Rassenkonflikten aus der Geschichte der Räuberei und des Krieges und schreitet gemeinsam in eine neue Ära der symbiotischen Evolution voran.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>51-人族定位与特质 (Position und Merkmale der Menschenrasse)</li><li>52-异族分类与共生 (Klassifizierung und Symbiose fremder Rassen)</li><li>05-万族共进基本纲领 (Grundprogramm des gemeinsamen Fortschritts aller Rassen)</li><li>40-共生宪法总纲 (Grundsätze der Symbiose-Verfassung)</li></ul>',30)])])}const c=n(t,[["render",a]]);export{m as __pageData,c as default};
